"""Actual bounded CBMC proofs plus falsification and assumption controls."""
from pathlib import Path
import argparse,subprocess,hashlib,json,datetime
ROOT=Path(__file__).resolve().parents[1]
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--cbmc',default=str(Path.home()/'cmastery-b06-tools/usr/bin/cbmc'));ap.add_argument('--report',default='research/v5/expansion/b06/solver_validation.json');a=ap.parse_args();rows=[];ref=ROOT/'assessor/verification_fuzzing/core.c';inc=ROOT/'labs/verification_fuzzing/include';add=ROOT/'labs/verification_fuzzing/targets/cbmc_add.c';structures=add.with_name('cbmc_structures.c')
 for label,src,flags,expected,marker in [('checked add',add,[],0,'VERIFICATION SUCCESSFUL'),('add overflow mutant',add,['-DB06_MUTATION=1'],10,'VERIFICATION FAILED'),('search ring bounded',structures,[],0,'VERIFICATION SUCCESSFUL'),('search duplicate mutant',structures,['-DB06_MUTATION=2'],10,'VERIFICATION FAILED'),('ring full mutant',structures,['-DB06_MUTATION=3'],10,'VERIFICATION FAILED'),('reachable assumptions witness',structures,['-DWITNESS'],10,'assumption domain is reachable'),('vacuous assumptions demonstration',structures,['-DWITNESS','-DVACUOUS'],0,'VERIFICATION SUCCESSFUL'),('insufficient unwind detected',structures,['--unwind','2'],10,'unwinding assertion')]:
  cmd=[a.cbmc,str(src),str(ref),'-I',str(inc),'--bounds-check','--pointer-check','--signed-overflow-check','--unwinding-assertions',*(['--unwind','9'] if '--unwind' not in flags else []),*flags]
  try:r=subprocess.run(cmd,text=True,capture_output=True,timeout=60);rows.append(dict(label=label,command=cmd,returncode=r.returncode,stdout=r.stdout,stderr=r.stderr,passed=r.returncode==expected and marker in r.stdout+r.stderr,expected=expected,marker=marker))
  except (OSError,subprocess.TimeoutExpired) as e:rows.append(dict(label=label,command=cmd,passed=False,error=str(e)))
 version=subprocess.run([a.cbmc,'--version'],capture_output=True,text=True);pins={p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in [ref,inc/'core.h',add,structures,Path(__file__)]};report=dict(passed=all(r['passed'] for r in rows),version=version.stdout,input_sha256=pins,recorded_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),checks=rows,scope='uint32 checked addition unrestricted operands; sorted arrays <=8; ring capacities<=8 over8 transitions; complete unwinding checks within these bounds',limitations=['Assumed sorted input and valid initial ring; no comparator inconsistency or multi-thread weak-memory proof','Vacuous demonstration is intentionally a successful solver result with an empty domain, not accepted evidence','External proof audit and independent learner transfer are separate']);(ROOT/a.report).write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(dict(passed=report['passed'],checks=len(rows),failures=[r['label'] for r in rows if not r['passed']])));return 0 if report['passed'] else 1
if __name__=='__main__':raise SystemExit(main())
